<?php elseif($page==='patients'): ?><h1>Pacientes</h1><p>Contatos reunidos a partir dos agendamentos.</p><form method="get" class="inline"><input type="hidden" name="page" value="patients"><input aria-label="Buscar paciente" name="q" placeholder="Buscar nome ou telefone" value="<?=e($_GET['q']??'')?>"><button>Buscar</button></form><div class="card"><?php $q='%'.($_GET['q']??'').'%'; $patients=query('SELECT name,phone,COUNT(*) AS total,MAX(starts) AS last_visit FROM appointments WHERE name LIKE ? OR phone LIKE ? GROUP BY name,phone ORDER BY name LIMIT 200',[$q,$q])->fetchAll(); if(!$patients) echo '<p>Nenhum paciente encontrado.</p>'; foreach($patients as $p): ?><div class="list-row"><div><b><?=e($p['name'])?></b><p><?=e($p['phone'])?></p></div><span><?=$p['total']?> reservas<br><small>Última data: <?=date('d/m/Y',strtotime($p['last_visit']))?></small></span></div><?php endforeach ?></div>
