<?php elseif($page==='settings'): ?><h1>Configurações</h1><div class="card"><h2>Disponibilidade</h2><p>Novos horários começam a cada 30 minutos, dentro do expediente. Alterações não movem reservas existentes.</p><form method="post"><?=token()?><input type="hidden" name="action" value="settings"><div class="two"><label>Abertura<input type="time" name="open" value="<?=e(setting('open'))?>" required></label><label>Fechamento<input type="time" name="close" value="<?=e(setting('close'))?>" required></label></div><fieldset><legend>Dias de atendimento</legend><div class="days"><?php foreach(['1'=>'Seg','2'=>'Ter','3'=>'Qua','4'=>'Qui','5'=>'Sex','6'=>'Sáb','7'=>'Dom'] as $v=>$label): ?><label class="check"><input type="checkbox" name="days[]" value="<?=$v?>" <?=in_array((string)$v,explode(',',setting('days')),true)?'checked':''?>><?=$label?></label><?php endforeach ?></div></fieldset><label>Intervalo entre atendimentos (minutos)<input type="number" name="gap" min="0" max="120" value="<?=e(setting('gap'))?>" required></label><button>Salvar disponibilidade</button></form></div><div class="card"><h2>Alterar senha</h2><form method="post"><?=token()?><input type="hidden" name="action" value="password"><label>Senha atual<input type="password" name="current" autocomplete="current-password" required></label><label>Nova senha<input type="password" name="password" minlength="10" autocomplete="new-password" required></label><button>Atualizar senha</button></form></div>
<?php endif ?></section></div><script src="confirm.js" defer></script>
